import { Component, inject, linkedSignal, signal } from '@angular/core';
import { LOCALES, Locale, UserLocale } from '../../core/locale';
import { Session } from '../../core/session';
import { AuditViewer } from '../audit-viewer/audit-viewer';
import { Activity } from '../activity/activity';
import { Duplicates } from '../duplicates/duplicates';
import { Grades } from '../grades/grades';
import { Holidays } from '../holidays/holidays';
import { NotesList } from '../notes/notes';
import { People } from '../people/people';
import { Settings } from '../settings/settings';
import { SnapshotCompare } from '../snapshot-compare/snapshot-compare';
import { TemplatesList } from '../templates/templates';
import { TreeSearch } from '../tree-search/tree-search';
import { SheetCompare } from '../sheet-compare/sheet-compare';
import { VoidReasonsList } from '../void-reasons/void-reasons';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [Activity, AuditViewer, Duplicates, Grades, Holidays, NotesList, People, Settings, SheetCompare, SnapshotCompare, TemplatesList, TreeSearch, VoidReasonsList],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>
      <form (submit)="saveLocale($event)">
        <label for="user-locale">Locale</label>
        <select
          id="user-locale"
          data-testid="user-locale"
          (change)="localeInput.set(locale(value($event))); localeError.set(null)"
        >
          @for (l of locales; track l) {
            <option [value]="l" [selected]="l === localeInput()">{{ l }}</option>
          }
        </select>
        <button type="submit" data-testid="user-locale-save">Save locale</button>
        <span>Locale <strong data-testid="user-locale-current">{{ userLocale.locale() }}</strong></span>
        @if (localeError(); as error) {
          <p role="alert" data-testid="user-locale-error">{{ error }}</p>
        }
      </form>
      <form (submit)="load($event)">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetId()"
          (input)="sheetId.set(value($event)); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
        @if (sheetError(); as error) {
          <p role="alert" data-testid="sheet-error">{{ error }}</p>
        }
      </form>
      @if (session.sheet(); as sheet) {
